/** Resolve a wall time, choosing the earlier occurrence in a fold and moving
 * forward by the gap when the requested wall time does not exist. */
function localInstant(date: string, hour: number, timeZone: string): Date {
  const [year, month, day] = date.split("-").map(Number);
  const target = Date.UTC(year, month - 1, day, hour);
  const offsets = new Set<number>();
  for (const delta of [-2, -1, 0, 1, 2]) {
    const sample = target + delta * DAY_MS;
    const p = localParts(new Date(sample), timeZone);
    offsets.add(Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - sample);
  }
  const candidates = [...offsets].map((offset) => {
    const instant = target - offset;
    const p = localParts(new Date(instant), timeZone);
    const wall = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
    return { instant, wall };
  });
  const exact = candidates.filter((candidate) => candidate.wall === target)
    .sort((a, b) => a.instant - b.instant)[0];
  const after = candidates.filter((candidate) => candidate.wall > target)
    .sort((a, b) => a.wall - b.wall || a.instant - b.instant)[0];
  return new Date((exact ?? after ?? candidates[0]).instant);
}

/** Shift a calendar date without assuming its day is 24 hours long. */
export function shiftLocalDate(date: string, days: number): string {
  const [year, month, day] = date.split("-").map(Number);
  return new Date(Date.UTC(year, month - 1, day + days)).toISOString().slice(0, 10);
}

export function startOfLocalDate(date: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(localInstant(date, 0, timeZone));
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return startOfLocalDate(localDate(toIsoTimestamp(reference), timeZone), timeZone);
}

/** A due date remains current until its local calendar day ends. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

